const crypto = require('crypto');
const secret = $env.CONTINUITY_SYNC_SECRET;
if (!secret || secret.length < 32) throw new Error('Continuity signing secret is not configured.');
const base = ($env.LARAVEL_API_URL || '').replace(/\/$/, '');
if (!/^https:\/\/[^\s?#]+$/.test(base) && base !== 'http://host.docker.internal:8000') throw new Error('Configure HTTPS Laravel URL or the documented local host URL.');
const path = '/api/internal/n8n/continuity-sync';
const timestamp = String(Math.floor(Date.now() / 1000));
const requestId = crypto.randomUUID();
const body = JSON.stringify({request_id: requestId, source: 'n8n'});
const signature = crypto.createHmac('sha256', secret).update(timestamp + '\nPOST\n' + path + '\n' + body).digest('hex');
return [{json: {url: base + path, timestamp, request_id: requestId, body, signature}}];

const data = $input.first().json.data;
if (!data || typeof data.run_id !== 'string' || !['queued', 'running', 'completed'].includes(data.status)) throw new Error('Laravel did not acknowledge a continuity run.');
return [{json: {run_id: data.run_id, status: data.status}}];
